// Convenience: every subject that currently has a hardwired preset.
// Preset sequences that span several grades prefix each topic with its grade
// ("Grade 2 · ...", "Graad 2 · ...", "Kereite ya 2 · ..."). A class only teaches
// its own grade, so the sequence is narrowed before it is copied onto a class.
const GRADE_PREFIX = /^(?:Grade|Graad|Kereite ya|IBanga)\s+(R|\d+)\s+·/;

export function presetSequenceForGrade(preset: PresetEntry, grade: number): string[] {
  if (preset.gradeMin === preset.gradeMax) return preset.sequence;
  const token = grade === GRADE_R ? "R" : String(grade);
  const scoped = preset.sequence.filter((topic) => GRADE_PREFIX.exec(topic)?.[1] === token);
  // A multi-grade sequence without any grade prefixes (e.g. a document that has
  // not yet been split per grade) is used whole as a fallback.
  return scoped.length ? scoped : preset.sequence;
}

export function presetSubjects() {
  return Array.from(new Set(PRESET_CURRICULA.map((entry) => entry.subject)));
}

// Longest hardwired subject label. Route schemas validate the subject a client
// posts, and the dropdowns are fed straight from this catalog, so the limit has
// to be derived from the catalog itself — a fixed cap silently rejects valid
// preset subjects once a longer label (e.g. an African-language FAL title) is
// added.
export const PRESET_SUBJECT_MAX_LENGTH = PRESET_CURRICULA.reduce(
  (longest, entry) => Math.max(longest, entry.subject.length),
  0,
);

// Subjects a given grade may open a class for; a subject can appear in several
// phases (e.g. Mathematics in the Foundation and Intermediate Phase).
export function presetSubjectsForGrade(grade: number) {
  return PRESET_CURRICULA.filter((entry) => grade >= entry.gradeMin && grade <= entry.gradeMax).map((entry) => entry.subject);
}

export function presetForSubject(subject: string, grade: number): PresetEntry | null {
  return PRESET_CURRICULA.find((entry) => entry.subject === subject && grade >= entry.gradeMin && grade <= entry.gradeMax) ?? null;
}

// Upserts the registry into the catalog table (idempotent — used by the
// schema bootstrap and useful when the registry gains entries).
export async function syncPresetCurricula() {
  for (const entry of PRESET_CURRICULA) {
    await db
      .insert(presetCurriculaTable)
      .values({
        phase: entry.phase,
        subject: entry.subject,
        gradeMin: entry.gradeMin,
        gradeMax: entry.gradeMax,
        sourceName: entry.sourceName,
        sequence: entry.sequence,
        assessmentGuide: entry.assessmentGuide || null,
      })
      .onConflictDoUpdate({
        target: [presetCurriculaTable.phase, presetCurriculaTable.subject, presetCurriculaTable.gradeMin, presetCurriculaTable.gradeMax],
        set: {
          sequence: entry.sequence,
          sourceName: entry.sourceName,
          // Only overwrite the guide from the registry when a non-empty one is
          // hardwired; uploaded guides (until a set endpoint ships) are kept.
          ...(entry.assessmentGuide ? { assessmentGuide: entry.assessmentGuide } : {}),
        },
      });
  }
}

// Gate: a class can only be created against a preset subject at a covered
// grade. Returns the preset on success, or null when the subject is locked.
export async function resolvePresetForClass(subject: string, grade: number) {
  const preset = presetForSubject(subject, grade);
  if (!preset) return null;
  const [row] = await db
    .select()
    .from(presetCurriculaTable)
    .where(
      and(
        eq(presetCurriculaTable.subject, preset.subject),
        eq(presetCurriculaTable.gradeMin, preset.gradeMin),
        eq(presetCurriculaTable.gradeMax, preset.gradeMax),
      ),
    )
    .limit(1);
  return { preset, row: row ?? null };
}

export async function listPresetCurricula() {
  const rows = await db
    .select()
    .from(presetCurriculaTable)
    .orderBy(sql`${presetCurriculaTable.gradeMin}, ${presetCurriculaTable.subject}`);
  return rows.map((row) => ({
    id: row.id,
    phase: row.phase,
    subject: row.subject,
    gradeMin: row.gradeMin,
    gradeMax: row.gradeMax,
    sourceName: row.sourceName,
    sequence: row.sequence,
    hasAssessmentGuide: Boolean(row.assessmentGuide),
  }));
}
